sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var risk = (current.business_risk || '').toLowerCase();
    var pri = parseInt(current.priority, 10) || 4;

    var targetGroupName = 'Retail Customer Care';
    if (risk === 'critical' || risk === 'high' || pri <= 2) {
        targetGroupName = 'Retail Escalation Desk';
    }

    var grp = new GlideRecord('sys_user_group');
    grp.addQuery('name', targetGroupName);
    grp.setLimit(1);
    grp.query();
    if (grp.next()) {
        current.assignment_group = grp.getUniqueValue();
    }

    if (current.state == 1 && targetGroupName === 'Retail Escalation Desk') {
        current.state = 2; // Work in Progress for Escalations
        current.work_notes = "Complaint routed to " + targetGroupName + ". Investigation initiated.";
    }
})(current, previous);
